package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;

final class IncidentTriageBrowserAcceptance {
 static void click(Page page,String name){page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName(name).setExact(true)).press("Enter");}
 static void run(BrowserTest h)throws Exception{
  String record,group,other;try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.createAccount(db,map("name","TriageBrowserOperator","role","agent","password",WorkflowSupport.PASSWORD));String actor=RecordAccess.owner(db,"TriageBrowserOperator");group=Service.create(db,"sys_user_group",map("short_description","Network response"),"admin").get("sys_id").toString();other=Service.create(db,"sys_user_group",map("short_description","Workplace service desk"),"admin").get("sys_id").toString();db.update("INSERT INTO os_group_member(group_id,user_id) VALUES(?,?)",group,actor);db.update("INSERT INTO os_group_member(group_id,user_id) VALUES(?,?)",other,actor);record=Service.create(db,"incident",map("short_description","Review office connectivity <script>","description","Several colleagues cannot connect to the network"),"admin").get("sys_id").toString();db.connection.commit();}
  try(var provider=new RecordQuestionsAcceptance.Provider(h.store,h.environment);var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   provider.settings.put("AI_TRIAGE_ENABLED","true");var proposed=IncidentTriageAcceptance.draft(group);proposed.put("rationale","Network impact needs human confirmation <script>");provider.answer.set(JSON.writeValueAsString(proposed));var page=context.newPage();h.login(page,"TriageBrowserOperator");page.navigate(h.base()+"/record/incident/"+record);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Review AI incident triage")).press("Enter");click(page,"Preview triage context");assertEquals(0,provider.calls.get());assertThat(page.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Exactly what will be sent"))).isVisible();assertThat(page.locator("pre")).containsText("Several colleagues cannot connect");page.getByLabel("Send this incident and group context to the configured provider").check();click(page,"Generate a triage proposal");assertEquals(1,provider.calls.get());assertThat(page.locator("main")).containsText("Status: proposed");assertThat(page.locator("main")).containsText("Network impact needs human confirmation <script>");page.getByLabel("Reviewed priority").selectOption("3");page.getByLabel("Reviewed assignment team").selectOption(other);page.getByLabel("Reviewed rationale").fill("Reviewed impact: route to the workplace team before escalation");click(page,"Review exact incident change");assertThat(page.locator("main")).containsText("Set priority to 3 and assignment group to Workplace service desk");try(var db=h.store.open()){assertEquals(0,db.count("SELECT revision FROM os_record WHERE sys_id=?",record));}ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/triage-reviewed-light.png")).setFullPage(true));page.getByLabel("Apply this exact priority and assignment team change").check();click(page,"Apply reviewed triage");assertThat(page.locator("main")).containsText("Status: completed");assertThat(page.locator("main")).containsText("Verified execution receipt");assertThat(page.locator("main")).containsText("Saved team: Workplace service desk");assertThat(page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Apply reviewed triage"))).hasCount(0);page.reload();assertEquals(1,provider.calls.get());click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertThat(page.locator("main script")).hasCount(0);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/triage-applied-dark.png")).setFullPage(true));page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Incident workspace").setExact(true)).press("Enter");assertThat(page.locator("select[name=priority]")).hasValue("3");assertThat(page.locator("input[name=assignment_group]")).hasValue(other);
  }
 }
}
